  1	import type { ChatAnswer, ChatStreamEvent } from "./use-chat-request";
  2	
  3	export type CallCaption = { id: number; role: "user" | "assistant"; text: string };
  4	export type CallTask = { requestId: string; text: string; step: string; status: "running" | "done" | "failed" | "canceled"; delegationId: string | null; cards: string[] };
  5	export type CallAsk = (payload: { conversationId: string; requestId: string; message: string; context: Record<string, unknown> }, onEvent: (event: ChatStreamEvent) => void)
  6	  => Promise<{ ok: boolean; status?: number; body: { error?: string } & Partial<ChatAnswer> }>;
  7	
  8	type ServerEvent = { type: string; delta?: string; start_ms?: number; end_ms?: number; offset_ms?: number | null; delegation?: { id: string }; error?: { message?: string }; message?: string };
  9	type Deps = {
 10	  conversationId: string;
 11	  /** Sends a client event on the oai-events data channel. */
 12	  send: (event: Record<string, unknown>) => void;
 13	  ask: CallAsk;
 14	  /** Called when a task's answer is saved in the chat, so the chat view can show it. */
 15	  onAnswer?: (question: string, answer: ChatAnswer) => void;
 16	  onChange: () => void;
 17	  /** Notes what the call decided and when, for debugging a call. */
 18	  log?: (message: string) => void;
 19	  now?: () => number;
 20	  schedule?: (run: () => void, ms: number) => unknown;
 21	  newId?: () => string;
 22	};
 23	
 24	/** What each chat tool is doing, as a short progress line for the voice model. */
 25	const STEPS: Record<string, string> = {
 26	  finance_investigate: "searching transactions", transactions_search: "searching transactions", finance_detail: "reading a transaction", finance_entities: "looking up names",
 27	  finance_scenario: "comparing a what-if", analytics_cashflow: "adding up income and spending", accounts_list: "checking accounts", accounts_getBalances: "checking balances",
 28	  forecast_evaluate: "running the forecast", goals_list: "checking goals", wealth_list: "checking what you lent and own", recurring_list: "checking recurring payments", reviews_investigate: "reviewing finances",
 29	  reviews_start: "starting a deep review", imports_status: "checking imports", agents_findings: "reading agent findings", agents_decide: "making a confirmation card",
 30	  transaction_propose: "making a card", iou_propose: "making a loan card", balance_propose: "making a balance card", recurring_propose: "making a recurring card",
 31	  iou_findRepayments: "looking for repayments", call_replace_task: "replacing the earlier request", app_help: "checking how Moneo works",
 32	};
 33	export const stepFor = (tool: string) => STEPS[tool] ?? "working";
 34	
 35	/** The proposal card ids an answer shows, in order. */
 36	export function answerCards(answer: string) {
 37	  return [...new Set([...answer.matchAll(/```moneo-proposals?\n([\s\S]*?)```/g)].flatMap(match => match[1].match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) ?? []))];
 38	}
 39	/** An answer as words to speak: no card, chart or decision blocks, bounded. */
 40	export function spokenAnswer(answer: string, max = 1500) {
 41	  const text = answer.replace(/```[\w-]*\n[\s\S]*?```/g, "").replace(/[*_#`>|]/g, "").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/\s+/g, " ").trim();
 42	  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
 43	}
 44	
 45	export const SPEAKING_HOLD_MS = 700;
 46	/** Words still unclaimed after the user has been quiet this long were a request GPT-Live said yes to but never handed off. */
 47	export const UNCLAIMED_MS = 4000;
 48	/** GPT-Live taking words on ("on that one too", "let me check"), unlike "mm-hm" or "take your time". */
 49	const TAKES_ON = /\b(on (it|that|this)|too|as well|also|let me|i'?ll|checking|looking|making|adding|noted)\b/i;
 50	const SMALL_TALK = /\b(hi|hey|hello|yo|thanks|thank you|bye|good (morning|evening|night)|how are you( doing)?( today)?|i'?m (good|fine|okay)|okay|ok|yeah|yes|no|um+|uh+|mm+|mm-?hm|(can|could|would|will) you( also)?( please)?( tell me| say)?)\b/gi;
 51	const ASKS = /\?|\b(how much|what|when|where|who|which|why|check|show|tell|add|spent|spend|paid|pay|lent|lend|borrowed?|owe|bought|received|transfer|budget|save|balance|cancel|remove|change)\b/i;
 52	/** Transcript text as plain words, without sound tags like "[scoff]". */
 53	const plain = (text: string) => text.replace(/\[[^\]]*\]/g, "").replace(/\s+/g, " ").trim();
 54	/** Whether unclaimed words ask for something, rather than being small talk GPT-Live answered itself. */
 55	export function looksLikeRequest(text: string) {
 56	  const rest = text.replace(SMALL_TALK, " ").trim();
 57	  return rest.split(/\s+/).filter(Boolean).length >= 3 && ASKS.test(rest);
 58	}
 59	/** How long a hand-off with no new words waits for them to be transcribed. */
 60	export const LATE_WORDS_MS = 1500;
 61	export const SLOW_TASK_MS = 8000;
 62	/** Moneo silent this long after it began saying a result means it said all of it. The user's words are transcribed
 63	 * about a second late, so words arriving sooner than this were said over the result. */
 64	export const RESULT_DONE_MS = 2500;
 65	/** Moneo silent this long, with the mic quiet since, also means it said all of it: the mic hears the user at once,
 66	 * so nobody talked over it, and the next result follows without a long gap. */
 67	export const RESULT_PAUSE_MS = 300;
 68	/** Longest wait for Moneo to start saying a result before the next is handed over anyway. */
 69	export const RESULT_TURN_MS = 20_000;
 70	/** A pause this long ends the user's turn for handing over a result; people pause mid-sentence ("uh… like…"). */
 71	export const USER_PAUSE_MS = 1500;
 72	/** How long Moneo gets to answer an interruption before it is asked to finish the result it was cut off in. */
 73	export const RESUME_AFTER_MS = 3000;
 74	/** Added to every result handed over: what is still running is said once the result has been, as it stands then. */
 75	export const ONLY_THIS_RESULT = "Say this result now and don't mention other requests. Don't end with a question or wait for the user: if another result comes, go straight on with it.";
 76	
 77	/**
 78	 * Runs a voice call's tasks: each GPT-Live delegation (or typed message) becomes one /api/chat request, and its
 79	 * answer is handed back to be spoken: first finished, first said, one at a time, and never over the user.
 80	 */
 81	export class VoiceCallController {
 82	  captions: CallCaption[] = [];
 83	  tasks: CallTask[] = [];
 84	  error = "";
 85	  /** Words the user said that no hand-off has claimed yet, with when each piece began in the session. */
 86	  private heard: { text: string; start: number }[] = [];
 87	  /** What Moneo has said since the user last spoke. */
 88	  private reply = "";
 89	  private lastDelegation: string | null = null;
 90	  /** A request started from unclaimed words, which a late hand-off of the same words takes over instead of repeating. */
 91	  private unclaimedTask: string | null = null;
 92	  private answers = new Map<string, string>();
 93	  private lastUserSpeech = -Infinity;
 94	  private lastAssistantSpeech = -Infinity;
 95	  /** When Moneo was last audible in the call's audio. Transcript text runs ahead of the voice, so once the audio is
 96	   * metered it, not the transcript, says whether Moneo is talking. */
 97	  private lastAudible = -Infinity;
 98	  private metered = false;
 99	  /** When the user was last loud on the mic, once it is metered. */
100	  private lastMic = -Infinity;
101	  private micMetered = false;
102	  private outbox: { requestId?: string; delegationId: string | null; content: string }[] = [];
103	  private flushing = false;
104	  /** The result Moneo was last handed and when, until it has said all of it or was talked over. */
105	  private current: { requestId?: string; delegationId: string | null; content: string; at: number } | null = null;
106	  /** A result the user talked over, with what they said since, until Moneo is asked to finish it. */
107	  private cut: { requestId?: string; delegationId: string | null; content: string; words: string } | null = null;
108	  /** Requests the user has been told are still running, so they hear it once. */
109	  private announced = new Set<string>();
110	  private captionId = 0;
111	  /** A sound tag ("[scoff]") still open at the end of a role's last words, held until it closes. */
112	  private openTag: Record<CallCaption["role"], string> = { user: "", assistant: "" };
113	  private readonly now: () => number;
114	  private readonly schedule: (run: () => void, ms: number) => unknown;
115	  private readonly newId: () => string;
116	
117	  constructor(private readonly deps: Deps) {
118	    this.now = deps.now ?? (() => Date.now());
119	    this.schedule = deps.schedule ?? ((run, ms) => setTimeout(run, ms));
120	    this.newId = deps.newId ?? (() => crypto.randomUUID());
121	  }
122	
123	  get running() { return this.tasks.filter(task => task.status === "running"); }
124	  get cards() { return this.tasks.flatMap(task => task.cards); }
125	  /** When Moneo last made a sound: its metered voice once there is one, else its transcript. */
126	  private get lastMoneo() { return this.metered ? this.lastAudible : this.lastAssistantSpeech; }
127	  /** Someone is talking right now. */
128	  speaking(by: "user" | "moneo" | "any" = "any") {
129	    const last = by === "user" ? this.lastUserSpeech : by === "moneo" ? this.lastMoneo : Math.max(this.lastUserSpeech, this.lastMoneo);
130	    return this.now() - last < SPEAKING_HOLD_MS;
131	  }
132	  /** Moneo is talking, or between results it still has to say, so the call screen doesn't flick to listening. */
133	  get answering() {
134	    if (this.speaking("moneo") || this.outbox.length) return true;
135	    return !!this.current && this.lastMoneo <= this.current.at && this.now() - this.current.at < RESULT_TURN_MS;
136	  }
137	  /** Called while Moneo's voice is audible in the call. */
138	  heardMoneo() { this.metered = true; this.lastAudible = this.now(); }
139	  /** Called while the user is loud on the mic. */
140	  heardUser() { this.micMetered = true; this.lastMic = this.now(); }
141	
142	  /** Whether Moneo has said the result it was handed: it began, then went quiet with nobody talking over it. */
143	  private resultSaid() {
144	    const current = this.current;
145	    if (!current) return true;
146	    if (this.lastMoneo <= current.at) return this.now() - current.at > RESULT_TURN_MS;
147	    const micQuiet = this.micMetered && this.lastMic < this.lastMoneo;
148	    return this.now() - this.lastMoneo >= (micQuiet ? RESULT_PAUSE_MS : RESULT_DONE_MS);
149	  }
150	
151	  handle(event: ServerEvent) {
152	    switch (event.type) {
153	      case "session.input_transcript.delta": {
154	        // GPT-Live's transcript sometimes marks a break with "|" ("when is my| rent due").
155	        const delta = (event.delta ?? "").replace(/\|/g, " ");
156	        // Talking over a result GPT-Live is saying stops it, and the rest would be lost.
157	        if (this.current && this.lastMoneo > this.current.at && !this.resultSaid()) {
158	          this.cut = { ...this.current, words: "" };
159	          this.deps.log?.(`cut off: ${this.current.content.slice(0, 60)}`);
160	          this.current = null;
161	          this.resume();
162	        }
163	        if (this.cut) this.cut.words += delta;
164	        this.lastUserSpeech = this.now();
165	        this.reply = "";
166	        // Words without timing belong to the next hand-off, whatever its offset.
167	        this.heard.push({ text: delta, start: event.start_ms ?? event.end_ms ?? -Infinity });
168	        this.caption("user", delta);
169	        this.schedule(() => this.claimUnheard(), UNCLAIMED_MS);
170	        break;
171	      }
172	      case "session.output_transcript.delta":
173	        this.lastAssistantSpeech = this.now();
174	        this.caption("assistant", event.delta ?? "");
175	        this.reply += event.delta ?? "";
176	        this.claimTakenOn();
177	        break;
178	      case "session.delegation.created": {
179	        // The delegation carries no task text: it is what the user said up to its offset since the previous one;
180	        // words said after the offset belong to the next request.
181	        const id = event.delegation?.id;
182	        if (!id) break;
183	        this.lastDelegation = id;
184	        this.claim(id, event.offset_ms ?? Infinity);
185	        break;
186	      }
187	      case "error":
188	        this.error = event.error?.message ?? event.message ?? "The call had a problem";
189	        this.deps.onChange();
190	        break;
191	    }
192	  }
193	
194	  /**
195	   * Starts a hand-off's request from the words up to its offset. With none yet, a request already started from the
196	   * same unclaimed words answers through it; otherwise its words may still be on their way from the transcriber. A
197	   * hand-off that never gets words of its own starts nothing, so a request never runs twice.
198	   */
199	  private claim(delegationId: string, offset: number, wait = true) {
200	    // A word the user began before the hand-off is part of its request, even if it ended just after; later words
201	    // belong to the next one.
202	    const claimed = this.heard.filter(piece => piece.start < offset);
203	    this.heard = this.heard.filter(piece => piece.start >= offset);
204	    const words = plain(claimed.map(piece => piece.text).join(""));
205	    if (words) { this.unclaimedTask = null; this.start(words, delegationId); }
206	    else if (this.unclaimedTask) { this.update(this.unclaimedTask, { delegationId }); this.unclaimedTask = null; }
207	    else if (wait) this.schedule(() => this.claim(delegationId, offset, false), LATE_WORDS_MS);
208	    else this.deps.log?.("hand-off with no new words: nothing to start");
209	  }
210	
211	  /**
212	   * GPT-Live sometimes says it is on a request ("sure, I'll check that too") without handing it off. Once it says so,
213	   * the user's words since the last hand-off become their own request right away, apart from whatever they say next,
214	   * answered through the latest hand-off. If GPT-Live hands them off after all, that hand-off takes the request over.
215	   */
216	  private claimTakenOn() {
217	    if (!this.lastDelegation || !TAKES_ON.test(this.reply.slice(0, 80))) return;
218	    const text = plain(this.heard.map(piece => piece.text).join(""));
219	    // A word or two left after an early hand-off ("month") is not a request of its own.
220	    if (text.replace(SMALL_TALK, " ").trim().split(/\s+/).filter(Boolean).length < 3) return;
221	    this.heard = [];
222	    this.deps.log?.(`claimed words GPT-Live took on without a hand-off: ${text.slice(0, 60)}`);
223	    this.unclaimedTask = this.start(text, this.lastDelegation);
224	  }
225	
226	  /**
227	   * Words still unclaimed once the user has been quiet a while: a request GPT-Live never handed off becomes its own,
228	   * and small talk GPT-Live answered itself is dropped, so the next request doesn't start with it.
229	   */
230	  private claimUnheard() {
231	    if (this.now() - this.lastUserSpeech < UNCLAIMED_MS) return;
232	    const text = plain(this.heard.map(piece => piece.text).join(""));
233	    if (!looksLikeRequest(text)) { this.heard = []; return; }
234	    if (!this.lastDelegation) return;
235	    this.heard = [];
236	    this.deps.log?.(`claimed words GPT-Live never handed off: ${text.slice(0, 60)}`);
237	    this.unclaimedTask = this.start(text, this.lastDelegation);
238	  }
239	
240	
241	  /** A typed message starts a task directly; its answer is spoken the same way. */
242	  typed(text: string) {
243	    const message = text.trim();
244	    if (!message) return;
245	    this.captionId++;
246	    this.captions = [...this.captions, { id: this.captionId, role: "user", text: message }];
247	    this.start(message, null);
248	  }
249	
250	  private caption(role: CallCaption["role"], words: string) {
251	    // Sound tags are not words, and can arrive in pieces between the other side's words.
252	    let delta = (this.openTag[role] + words).replace(/\[[^\]]*\]/g, "");
253	    // A "[" that never closes within a few words was just a bracket.
254	    const open = delta.length - delta.lastIndexOf("[") > 40 ? -1 : delta.lastIndexOf("[");
255	    this.openTag[role] = open < 0 ? "" : delta.slice(open);
256	    if (open >= 0) delta = delta.slice(0, open);
257	    if (!delta) return;
258	    const last = this.captions.at(-1);
259	    if (last?.role === role) this.captions = [...this.captions.slice(0, -1), { ...last, text: last.text + delta }];
260	    else this.captions = [...this.captions, { id: ++this.captionId, role, text: delta.trimStart() }];
261	    this.deps.onChange();
262	  }
263	
264	  private update(requestId: string, change: Partial<CallTask>) {
265	    this.tasks = this.tasks.map(task => task.requestId === requestId ? { ...task, ...change } : task);
266	    this.deps.onChange();
267	  }
268	
269	  /**
270	   * What Moneo needs to answer one request on its own: the requests still being answered separately, the call so far
271	   * to resolve "that" or "also", and what this call has already answered.
272	   */
273	  private brief() {
274	    return {
275	      via: "call", input: "voice",
276	      runningTasks: this.running.slice(-5).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300) })),
277	      recentTurns: this.captions.slice(-6).map(caption => ({ role: caption.role, text: caption.text.slice(-300) })),
278	      answered: this.tasks.flatMap(task => {
279	        const answer = this.answers.get(task.requestId);
280	        return answer ? [{ text: task.text.slice(0, 150), answer: answer.slice(0, 300) }] : [];
281	      }).slice(-4),
282	    };
283	  }
284	
285	  private start(text: string, delegationId: string | null) {
286	    const requestId = this.newId();
287	    const context = this.brief();
288	    this.tasks = [...this.tasks, { requestId, text, step: "starting", status: "running", delegationId, cards: [] }];
289	    this.deps.onChange();
290	    this.watchSlow(requestId);
291	    void this.run(requestId, text, context);
292	    return requestId;
293	  }
294	
295	  private async run(requestId: string, text: string, context: ReturnType<VoiceCallController["brief"]>) {
296	    const label = `"${text.slice(0, 120)}"`;
297	    // Read when needed: a late hand-off can take a request over while it runs.
298	    const via = () => this.tasks.find(item => item.requestId === requestId)?.delegationId ?? null;
299	    try {
300	      const result = await this.deps.ask({ conversationId: this.deps.conversationId, requestId, message: text.slice(0, 4000), context }, event => {
301	        if (event.type !== "tool" || event.state !== "running") return;
302	        if (event.name === "call_replace_task") this.replaced((event.input as { requestId?: unknown } | undefined)?.requestId);
303	        const step = stepFor(event.name);
304	        this.update(requestId, { step });
305	        if (via()) this.deps.send({ type: "session.thinking.append", delegation_id: via(), content: `Working on ${label}: ${step}.` });
306	      });
307	      const task = this.tasks.find(item => item.requestId === requestId);
308	      // Canceled from the list, or stopped because a correction replaced it: nothing to say.
309	      if (task?.status === "canceled") return;
310	      if (result.status === 409) { this.update(requestId, { status: "canceled", step: "stopped" }); return; }
311	      if (!result.ok || !result.body.answer) throw new Error(result.body.error ?? "No answer");
312	      const cards = answerCards(result.body.answer);
313	      this.answers.set(requestId, spokenAnswer(result.body.answer));
314	      this.update(requestId, { status: "done", step: "answered", cards });
315	      this.deps.onAnswer?.(text, result.body as ChatAnswer);
316	      // A typed request has no hand-off to answer through, so the result says outright that it is to be spoken.
317	      const delegationId = via();
318	      this.deliver(requestId, delegationId, [`Result for ${label}${delegationId ? "" : " (typed by the user in the call; say the result to them now, in the language of their quoted words)"}: ${spokenAnswer(result.body.answer)}`,
319	        cards.length ? `${cards.length} card${cards.length > 1 ? "s" : ""} on screen to tap; nothing is saved until then.` : ""].filter(Boolean).join(" "));
320	    } catch {
321	      if (this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
322	      this.update(requestId, { status: "failed", step: "failed" });
323	      this.deliver(requestId, via(), `Moneo couldn't get an answer for ${label}. Tell the user briefly and ask if they want you to try again.`);
324	    }
325	  }
326	
327	  /** One short spoken update for a task that runs long, once nobody is talking. Re-checks every second; ends when the task does. */
328	  private watchSlow(requestId: string, delay = SLOW_TASK_MS) {
329	    this.schedule(() => {
330	      const task = this.tasks.find(item => item.requestId === requestId);
331	      if (task?.status !== "running" || this.announced.has(requestId)) return;
332	      // Never in the middle of saying a result, or before one waiting to be said.
333	      if (this.speaking() || !this.resultSaid() || this.cut || this.outbox.length) return this.watchSlow(requestId, 1000);
334	      this.stillWorking([task]);
335	    }, delay);
336	  }
337	
338	  /**
339	   * Once Moneo has said a result and has no other to say next, it says what is still running, read right then, so it
340	   * never says it is waiting on a request that has finished. Re-checks every 300 ms; ends once a newer result goes out.
341	   */
342	  private followUp(handed: VoiceCallController["current"]) {
343	    this.schedule(() => {
344	      if (this.current !== handed || this.cut || this.outbox.length) return;
345	      if (this.speaking() || !this.resultSaid()) return this.followUp(handed);
346	      const waiting = this.running.filter(task => !this.announced.has(task.requestId));
347	      if (waiting.length) this.stillWorking(waiting);
348	    }, 300);
349	  }
350	
351	  private stillWorking(tasks: CallTask[]) {
352	    tasks.forEach(task => this.announced.add(task.requestId));
353	    const names = tasks.map(task => `"${task.text.slice(0, 120)}" (${task.step})`).join(", ");
354	    this.deps.send({ type: "session.commentary.append", delegation_id: tasks[0].delegationId,
355	      content: `Still working on ${names}. Say so in a few words${tasks.some(task => task.delegationId) ? "" : ", in the language of their quoted words"}.` });
356	  }
357	
358	  /** Results queue in the order they finish. */
359	  private deliver(requestId: string, delegationId: string | null, content: string) {
360	    this.outbox.push({ requestId, delegationId, content });
361	    this.flush();
362	  }
363	
364	  /**
365	   * A correction is replacing an earlier request: its result is not said, so Moneo never gives the old answer before
366	   * the corrected one. The server stops it or dismisses its cards.
367	   */
368	  private replaced(requestId: unknown) {
369	    const task = this.tasks.find(item => item.requestId === requestId);
370	    if (!task || task.status === "failed" || task.status === "canceled") return;
371	    this.outbox = this.outbox.filter(item => item.requestId !== task.requestId);
372	    // Nor is the rest of it said if the user cut it off.
373	    if (this.cut?.requestId === task.requestId) this.cut = null;
374	    this.update(task.requestId, { status: "canceled", step: "replaced" });
375	  }
376	
377	  /**
378	   * Hands over the next result once Moneo has said the previous one and nobody is talking. A result never says what
379	   * else is still running: by the time Moneo reaches the end of it, that may have finished too.
380	   */
381	  private flush() {
382	    if (this.flushing || !this.outbox.length || this.cut) return;
383	    if (this.speaking("user") || this.now() - this.lastUserSpeech < USER_PAUSE_MS || !this.resultSaid()) {
384	      this.flushing = true;
385	      this.schedule(() => { this.flushing = false; this.flush(); }, 300);
386	      return;
387	    }
388	    const { requestId, delegationId, content } = this.outbox.shift()!;
389	    this.current = { requestId, delegationId, content, at: this.now() };
