260	   260	/**
261	   261	 * A spoken correction replaces a still-running call request. One that has made no card yet is stopped; one that has
262	   262	 * made cards finishes first and its open cards are then dismissed as replaced, so nothing is half-done or duplicated.
263	   263	 */
264	   264	export async function replaceCallTask(supabase: SupabaseClient, { workspaceId, conversationId, requestId }: { workspaceId: string; conversationId: string; requestId: string },
265	   265	  { pollMs = 1000, maxWaitMs = 80_000, sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms)) } = {}) {
266	   266	  const status = async () => {
267	   267	    const { data, error } = await supabase.from("chat_requests").select("status").eq("workspace_id", workspaceId).eq("conversation_id", conversationId).eq("id", requestId).maybeSingle();
268	   268	    if (error) throw new Error(error.message);
269	   269	    return (data?.status as string | undefined) ?? null;
270	   270	  };
271	   271	  const first = await status();
272	   272	  if (!first) return { outcome: "not_found" as const, note: "No such request in this call; just answer the new request." };
273	   273	  const cards = await supabase.from("agent_proposals").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("chat_request_id", requestId);
274	   274	  if (cards.error) throw new Error(cards.error.message);
275	   275	  if (first === "running" && !cards.count) {
276	   276	    const canceled = await supabase.rpc("cancel_chat_request", { p_request_id: requestId });
277	   277	    if (canceled.error) throw new Error(canceled.error.message);
278	   278	    // It may have made a card between the check and the cancel.
279	   279	    const dismissed = await dismissCards(supabase, workspaceId, requestId);
280	   280	    return { outcome: "stopped" as const, dismissed, note: "The earlier request was stopped. Answer the corrected request now." };
281	   281	  }
282	   282	  let current = first;
283	   283	  for (let waited = 0; current === "running" && waited < maxWaitMs; waited += pollMs) { await sleep(pollMs); current = (await status()) ?? "missing"; }
284	   284	  const dismissed = await dismissCards(supabase, workspaceId, requestId);
285	   285	  return { outcome: current === "running" ? "still_running" as const : "replaced" as const, dismissed,
286	   286	    note: `${dismissed ? `${dismissed} card(s) from the earlier request were dismissed as replaced. ` : ""}Answer the corrected request now.` };
287	   287	}
