552	   552	export function boundTranscript(turns: { role: "user" | "assistant"; text: string }[]): CallTurn[] {
553	   553	  const kept = turns.flatMap(turn => turn.text.trim() ? [{ role: turn.role, text: turn.text.trim().slice(0, 4000) }] : []).slice(-400);
