563	   563	/** Long calls keep their start and end, so the prompt stays bounded. */
564	   564	export function summaryInput(transcript: CallTurn[], limit = SUMMARY_INPUT_CHARS) {
565	   565	  const text = transcript.map(turn => `${turn.role === "user" ? "User" : "Moneo"}: ${turn.text}`).join("\n");
566	   566	  return text.length <= limit ? text : `${text.slice(0, limit / 2)}\n[…]\n${text.slice(-limit / 2)}`;
567	   567	}
