570	   570	export function parseSummary(text: string) {
571	   571	  const bullets = text.split("\n").map(line => line.trim()).filter(line => /^[-•*]\s+\S/.test(line))
572	   572	    .map(line => `- ${line.replace(/^[-•*]\s+/, "").slice(0, 300)}`).slice(0, 4);
573	   573	  return bullets.length ? bullets.join("\n") : null;
574	   574	}
